function drawStation(b,p){ctx.save();let stationTime=performance.now()/1000;ctx.translate(p.x,p.y+Math.sin(stationTime*.8)*1.8);let scale=Math.min(2.8,Math.max(.02,p.r/100));ctx.rotate(-.16+Math.sin(stationTime*.35)*.012);ctx.scale(scale,scale);function solarPanel(x,y,w,h,angle=0){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle='#09233c';ctx.strokeStyle='rgba(101,185,221,.8)';ctx.lineWidth=2;ctx.fillRect(-w/2,-h/2,w,h);ctx.strokeRect(-w/2,-h/2,w,h);ctx.strokeStyle='rgba(72,148,197,.62)';ctx.lineWidth=1;for(let i=1;i<5;i++){ctx.beginPath();ctx.moveTo(-w/2+w*i/5,-h/2);ctx.lineTo(-w/2+w*i/5,h/2);ctx.stroke()}for(let i=1;i<8;i++){ctx.beginPath();ctx.moveTo(-w/2,-h/2+h*i/8);ctx.lineTo(w/2,-h/2+h*i/8);ctx.stroke()}ctx.restore()}solarPanel(-155,-4,42,92,-.12);solarPanel(122,-77,30,67,.08);solarPanel(122,77,30,67,-.08);solarPanel(290,-7,95,19,-.03);ctx.strokeStyle='rgba(121,207,226,.8)';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-190,0);ctx.lineTo(315,0);ctx.stroke();ctx.strokeStyle='rgba(203,227,225,.65)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-195,-5);ctx.lineTo(300,-5);ctx.moveTo(-195,5);ctx.lineTo(300,5);ctx.stroke();for(let x of [-178,-135,-88,55,177,250,300]){ctx.fillStyle=x===-88||x===55?'#183a4c':'#254d5d';ctx.strokeStyle='#aacdc9';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(x-13,-9,26,18,5);ctx.fill();ctx.stroke();ctx.fillStyle=x===55?'#8df6ea':'#f7c77e';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(x,0,2.5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}let metal=ctx.createLinearGradient(-100,-105,80,110);metal.addColorStop(0,'#d4e6df');metal.addColorStop(.3,'#557985');metal.addColorStop(.55,'#c1d5ce');metal.addColorStop(1,'#354f5d');ctx.beginPath();ctx.ellipse(-25,0,79,112,0,0,Math.PI*2);ctx.ellipse(-25,0,63,94,0,0,Math.PI*2,true);ctx.fillStyle=metal;ctx.fill('evenodd');ctx.strokeStyle='rgba(216,244,232,.92)';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(-25,0,79,112,0,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='rgba(89,187,207