function drawAsteroid(b,p){let seed=0;for(let i=0;i<b.id.length;i++)seed=(seed*31+b.id.charCodeAt(i))>>>0;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};ctx.save();ctx.translate(p.x,p.y);ctx.rotate(rnd()*Math.PI*2);let sides=p.r>45?18:12,points=[];for(let i=0;i<sides;i++){let a=i/sides*Math.PI*2,rad=p.r*(.72+rnd()*.38);points.push([Math.cos(a)*rad,Math.sin(a)*rad])}function outline(){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath()}let rock=ctx.createLinearGradient(-p.r,-p.r,p.r,p.r);rock.addColorStop(0,'#c3b8a8');rock.addColorStop(.38,b.color);rock.addColorStop(1,'#403d3a');outline();ctx.fillStyle=rock;ctx.fill();ctx.save();outline();ctx.clip();for(let i=0;i<sides;i++){let a=points[i],c=points[(i+1)%sides];ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(a[0],a[1]);ctx.lineTo(c[0],c[1]);ctx.closePath();ctx.fillStyle=`rgba(${rnd()>.53?'224,211,193':'30,28,25'},${.05+rnd()*.16})`;ctx.fill()}let craters=p.r>100?9:p.r>30?5:2;for(let i=0;i<craters;i++){let x=(rnd()-.5)*p.r*1.05,y=(rnd()-.5)*p.r*1.05,rx=p.r*(.045+rnd()*.105),ry=rx*(.55+rnd()*.35),angle=rnd()*Math.PI;ctx.beginPath();ctx.ellipse(x,y,rx,ry,angle,0,Math.PI*2);ctx.fillStyle='rgba(34,30,26,.24)';ctx.fill();ctx.beginPath();ctx.ellipse(x-rx*.12,y-ry*.18,rx*.78,ry*.72,angle,Math.PI*1.02,Math.PI*1.95);ctx.strokeStyle='rgba(225,212,192,.22)';ctx.lineWidth=Math.max(1,p.r*.009);ctx.stroke()}ctx.restore();outline();ctx.strokeStyle='rgba(31,31,29,.8)';ctx.lineWidth=Math.max(1,p.r*.025);ctx.stroke();let damage=asteroidDamage[b.id]||0;if(damage>0){ctx.strokeStyle='rgba(255,158,86,.8)';ctx.lineWidth=Math.max(1,p.r*.012);for(let i=0;i<Math.min(4,Math.ceil(damage/24));i++){ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo((rnd()-.5)*p.r*1.3,(rnd()-.5)*p.r*1.3);ctx.stroke()}}ctx.beginPath();ctx.moveTo(points[1][0],points[1][1]);for(let i=2;i<Math.max(4,sides*.42);i++)ctx.lineTo(points[i][0],points[i][1]);ctx.strokeStyle='rgba(233,222,203,.36)';ctx.lineWidth=Math.max(1,p.r*.012);ctx.stroke();ctx.restore()}
function advanceRareAsteroids(dt){for(const asteroid of bodies){if(!asteroid.rare)continue;asteroid.phaseRemaining=Math.max(0,Number(asteroid.phaseRemaining||0)-dt);if(asteroid.moving){asteroid.x+=Number(asteroid.vx||0)*dt;asteroid.z+=Number(asteroid.vz||0)*dt;if(asteroid.phaseRemaining<=0){asteroid.moving=false;asteroid.vx=0;asteroid.vz=0}}}}
