function drawIceAsteroid(b,p){drawAsteroid(b,p);ctx.save();ctx.strokeStyle='rgba(168,247,255,.94)';ctx.shadowColor='#6feaff';ctx.shadowBlur=19;ctx.lineWidth=Math.max(1.6,p.r*.06);ctx.setLineDash([Math.max(3,p.r*.1),Math.max(2,p.r*.07)]);ctx.beginPath();ctx.arc(p.x,p.y,p.r*1.17,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='rgba(226,251,255,.72)';ctx.lineWidth=Math.max(1,p.r*.025);ctx.beginPath();ctx.moveTo(p.x-p.r*.35,p.y-p.r*.55);ctx.lineTo(p.x-p.r*.08,p.y-p.r*.12);ctx.lineTo(p.x-p.r*.24,p.y+p.r*.17);ctx.moveTo(p.x+p.r*.27,p.y-p.r*.38);ctx.lineTo(p.x+p.r*.05,p.y+.02*p.r);ctx.lineTo(p.x+p.r*.34,p.y+p.r*.39);ctx.stroke();ctx.restore()}function drawIceMoon(b,p){drawBody(b,p);ctx.save();ctx.strokeStyle='rgba(133,231,249,.88)';ctx.shadowColor='#6bdcf4';ctx.shadowBlur=15;ctx.lineWidth=Math.max(1,p.r*.035);ctx.setLineDash([Math.max(2,p.r*.12),Math.max(2,p.r*.1)]);ctx.beginPath();ctx.arc(p.x,p.y,p.r*1.12,0,Math.PI*2);ctx.stroke();ctx.restore()}function drawMiningEffect(now){if(!miningState.active)return;window.gameAudio?.play('mining');const target=bodies.find(body=>body.id===miningState.targetId);if(!target){miningState.active=false;return}const screen=project(target);if(dist3(player,target)>1800){miningState.active=false;miningState.status='Alvo fora do alcance';return}miningState.progress=Math.min(1,(now-miningState.started)/5000);if(screen&&now-miningState.lastSpawn>90){miningState.lastSpawn=now;for(let i=0;i<3;i++)miningState.particles.push({x:W/2+(Math.random()-.5)*10,y:H-82,vx:(screen.x-W/2)/45+(Math.random()-.5)*2,vy:(screen.y-(H-82))/45+(Math.random()-.5)*2,life:1,size:1+Math.random()*2,color:target.ice||target.iceSource?'#9defff':'#ffcf82'})}if(miningState.particles.length){for(let i=miningState.particles.length-1;i>=0;i--){const p=miningState.particles[i];p.x+=p.vx;p.y+=p.vy;p.life-=.035;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);if(p.life<=0)miningState.particles.splice(i,1)}ctx.globalAlpha=1}ctx.save();ctx.strokeStyle=target.ice||target.iceSource?'rgba(143,235,255,.75)':'rgba(255,192,112,.75)';ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=13;ctx.lineWidth=1.5;if(screen){ctx.beginPath();ctx.moveTo(W/2,H-82);ctx.lineTo(screen.x,screen.y);ctx.stroke()}ctx.restore();if(miningState.progress>=1){window.gameAudio?.play('miningDone');miningState.active=false;miningState.progress=0;if(target.rare)completeRareMining(target.code||target.id.replace('rare_asteroide_','rare_'));else if(target.ice||target.iceSource)completeIceMining(target.iceSource?'moon':'asteroid',target.iceSource?target.id:target.code);else{const gained=Math.min(missionSystem.remainingMaterialCapacity(),35+Math.floor(Math.random()*36));if(gained){miningState.oreCounts.Ferro+=gained;miningState.ore+=gained;miningState.status='MineraÃ§Ã£o conclu?da: +'+gained+' kg de ferro';savePosition()}else miningState.status='Compartimento cheio ? extraÃ§Ã£o interrompida'}}}function draw(){const nearbyStation=updateStationProximityTarget();advanceRareAsteroids(Math.min(.05,(performance.now()-(window.rareAsteroidFrame||performance.now()))/1000));window.rareAsteroidFrame=performance.now();ctx.clearRect(0,0,W,H);let horizon=H/2+player.pitch*130;let bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#030915');bg.addColorStop(.52,'#071522');bg.addColorStop(1,'#020711');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
for(let s of stars){let z=((s.z-player.speed*6)%10000+10000)%10000;if(z<60)z+=10000;let x=(s.x*W*.8+W/2-player.yaw*90)%(W+20);if(x<0)x+=W+20;x-=10;let y=(s.y*H*.8+H/2-player.pitch*80);ctx.globalAlpha=s.a*(.3+Math.min(1,900/z));ctx.fillStyle='#c8e8ff';ctx.fillRect(x,y,s.s*(1+Math.max(0,player.speed/40)),s.s)}ctx.globalAlpha=1;
// Ambient nebula swaths add depth without creating world objects.
let neb=ctx.createRadialGradient(W*.73,H*.63,1,W*.73,H*.63,Math.min(W,H)*.48);neb.addColorStop(0,'rgba(11,105,119,.17)');neb.addColorStop(1,'rgba(3,11,24,0)');ctx.fillStyle=neb;ctx.fillRect(0,0,W,H);
near=[];for(const b of bodies){if(destroyedAsteroids.has(b.id))continue;let d=dist3(player,b);if(d<81000)near.push({b,d});}near.sort((a,b)=>b.d-a.d);for(const o of near){let p=project(o.b);if(p&&p.r>.7)(stationIds.includes(o.b.id)?drawStation3DModel:o.b.type==='Asteroide'?(o.b.rare?drawRareAsteroid:o.b.ice?drawIceAsteroid:drawAsteroid):o.b.iceSource?drawIceMoon:drawBody)(o.b,p)}drawMiningEffect(performance.now());drawWeaponShots(performance.now());drawRemoteShips();drawWrecks();window.tractorSystem?.draw();drawStationBearing(nearbyStation);
