function updateHud(){let d=dist3(player,selected),orbitalLimit=Math.max(1800,selected.r*8),orbitButton=document.querySelector('#orbit');document.querySelector('#coord').textContent=`${String(Math.round(player.x)).padStart(5,'0')} ? ${String(Math.round(player.y)).padStart(5,'0')}`;document.querySelector('#coordz').textContent=`SETOR ${String(Math.floor(Math.abs(player.z)/45000)).padStart(2,'0')} / 450.000 PX`;document.querySelector('#heading').textContent=`${String(Math.round((player.yaw*180/Math.PI+3600)%360)).padStart(3,'0')}Â°`;document.querySelector('#pitchread').textContent=`${Math.round(player.pitch*57.3)}Â°`;document.querySelector('#targetname').textContent=selected.name;document.querySelector('#targetdist').textContent=fmt(d)+' km';document.querySelector('#navdist').textContent=fmt(d)+' km';document.querySelector('#speed').textContent=(player.speed*60).toFixed(0);document.querySelector('#navspeed').textContent=(player.speed*60).toFixed(0)+' km/s';document.querySelector('#energyReadout').textContent=energyUnits.toLocaleString('pt-BR')+' UE';document.querySelector('#hullReadout').textContent=shipHull+'%';document.querySelector('#hullReadout').style.color=shipHull<35?'#ff8c73':'#d8f4fa';document.querySelector('#nearby').textContent=String(near.filter(o=>o.d<12000&&!destroyedAsteroids.has(o.b.id)).length).padStart(2,'0');orbitButton.textContent=window.crewDocked?'DESACOPLAR E ORBITAR':orbitMode?'SAIR DA ORBITA':'INICIAR ORBITA';orbitButton.disabled=(!window.crewDocked&&!orbitMode&&d>orbitalLimit)||(window.crewDocked&&!window.crewCanUndock);document.querySelector('#orbitnote').textContent=orbitMode?'ORBITA ASSISTIDA ATIVA':window.crewDocked?(window.crewCanUndock?'DESACOPLE PARA INICIAR A ORBITA':'DESEMBARQUE A TRIPULACAO PARA ORBITAR'):d>orbitalLimit?`APROXIME-SE / ${fmt(d-orbitalLimit)} KM`:'DISTANCIA ORBITAL ALCANCADA';if(selected.type!=='Asteroide'&&bodySelect.value!==selected.id)bodySelect.value=selected.id;let routeButton=document.querySelector('#routeGo');routeButton.textContent=followTargetId?'INTERROMPER SEGUIMENTO':autopilot?'CANCELAR NAVEGAÃ‡ÃƒO':'NAVEGAR ATÃ‰ LÃ';document.querySelector('#routeStatus').textContent=followTargetId?'SEGUINDO '+followName.toUpperCase()+' ? '+fmt(followDistance)+' KM':autopilot?'PILOTO AUTOMÃTICO ? '+fmt(d)+' KM RESTANTES':routeMessage||'SELECIONE UM PLANETA OU LUA';document.querySelector('#weaponReadout').textContent=weaponSystem.installed?weaponLabel(weaponSystem.kind)+' | '+weaponSystem.damage+' DMG ? PK':'SEM SISTEMA';document.querySelector('#ammoReadout').textContent=weaponSystem.ammo+' / '+weaponSystem.maxAmmo;document.querySelector('#fuelReadout').textContent=fuelUnits.toLocaleString('pt-BR',{maximumFractionDigits:0})+' / '+fuelCapacityUnits.toLocaleString('pt-BR')+' U';document.querySelector('#combatStatus').textContent=combatMessage||(weaponSystem.installed?'PK ATIVO':'AGUARDANDO');document.querySelector('#mapPkStatus').textContent=weaponSystem.installed?'PK ATIVO':'PK OFF';document.querySelector('#mapPkStatus').style.color=weaponSystem.installed?'#ff777d':'#83e9cd';fireButton.textContent=weaponSystem.installed&&weaponSystem.ammo>0?'DISPARAR SPACE | '+weaponSystem.ammo:'SEM CANHAO / MUNICAO';fireButton.disabled=!weaponSystem.installed||weaponSystem.ammo<1;refreshMiningUi();missionSystem.update();refreshStationAccess();refreshCargoBay(miningState.oreCounts,credits,weaponSystem,fuelUnits,cargoCapacityKg,missionSystem.getPassengerCargo(),window.towSystem)}
function refreshMiningUi(){let panel=document.querySelector('.mining-panel'),button=document.querySelector('#mineButton'),isAsteroid=selected.type==='Asteroide'||!!selected.iceSource,d=dist3(player,selected),p=isAsteroid?project(selected):null,inRange=isAsteroid&&d<=1800;if(miningState.active&&selected.rare&&selected.moving){miningState.active=false;miningState.status='Asteroide raro em trÃ¢nsito'}if(miningState.active&&(selected.id!==miningState.targetId||!inRange)){miningState.active=false;miningState.status='Alvo fora do alcance de mineraÃ§Ã£o'}panel.classList.toggle('visible',isAsteroid);button.disabled=(!miningState.active&&!inRange)||(selected.rare&&selected.moving);button.textContent=selected.rare&&selected.moving?'ASTEROIDE EM TRÃ‚NSITO':miningState.active?'INTERROMPER EXTRAÃ‡ÃƒO':inRange?'INICIAR MINERAÃ‡ÃƒO':'APROXIME-SE PARA MINERAR';document.querySelector('#mineProgress').style.width=(miningState.active?miningState.progress*100:0)+'%';document.querySelector('#mineStatus').textContent=miningState.active?'Extraindo '+miningState.progress.toFixed(0)+'% ? mantenha a nave prÃ³xima':inRange?(selected.rare&&selected.moving?'Asteroide raro em trÃ¢nsito':'Asteroide no alcance ? sistema de mineraÃ§Ã£o pronto'):miningState.status;document.querySelector('#oreCount').textContent=miningState.ore+' kg';document.querySelector('#cargoIron').textContent=(miningState.oreCounts.Ferro||0)+' kg';document.querySelector('#cargoNickel').textContent=(miningState.oreCounts.Niquel||0)+' kg';document.querySelector('#cargoCobalt').textContent=(miningState.oreCounts.Cobalto||0)+' kg';document.querySelector('#cargoIce').textContent=(miningState.oreCounts.Gelo||0)+' kg'}
async function completeIceMining(kind,code){if(multiplayerEnabled){try{const result=await socialRequest(kind==='moon'?'moon-ice-mine':'ice-mine',kind==='moon'?{body_code:code}:{code});miningState.oreCounts={...miningState.oreCounts,...result.cargo};miningState.ore=Object.values(miningState.oreCounts).reduce((sum,value)=>sum+(Number(value)||0),0);miningState.status='Gelo extra?do: +'+Number(result.gained).toLocaleString('pt-BR')+' kg'+(result.body?' em '+result.body:'');const body=bodies.find(item=>item.id===selected.id);if(body)body.remainingIce=result.remainingIce;savePosition()}catch(error){miningState.status=error.message}}else{const body=bodies.find(item=>kind==='moon'?item.id===code:item.code===code),stock=body?(Number(body.remainingIce??body.iceKg)||0):0,amount=Math.min(missionSystem.remainingMaterialCapacity(),stock,120+Math.floor(Math.random()*180));if(amount>0){miningState.oreCounts.Gelo+=amount;miningState.ore+=amount;if(body){if(body.iceSource)body.iceKg=stock-amount;else body.remainingIce=stock-amount}miningState.status='Gelo extra?do: +'+amount+' kg';savePosition()}else miningState.status=stock?'Compartimento cheio ? gelo nÃ£o coletado':'Veio de gelo esgotado'}}function fireWeapon(){if(window.crewRole==='passenger'||stationScreen.classList.contains('open')||shipHull<=0)return;if(combatTargetId){attackRemoteShip(combatTargetId);return}if(!weaponSystem.installed){combatMessage='Armas indispon?veis ? instale um canhÃ£o no Porto Aurora';return}if(weaponSystem.ammo<=0){combatMessage='MuniÃ§Ã£o esgotada ? recarregue no Porto Aurora';return}window.gameAudio?.play('laser');weaponSystem.ammo--;let target=null,end={x:W*.5,y:H*.5},screen=selected.type==='Asteroide'&&!destroyedAsteroids.has(selected.id)?project(selected):null;if(screen&&screen.x>=0&&screen.x<=W&&screen.y>=0&&screen.y<=H&&dist3(player,selected)<30000){target=selected;end={x:screen.x,y:screen.y}}weaponShots.push({x:W*.5,y:H-90,endX:end.x,endY:end.y,born:performance.now(),duration:190,targetId:target?target.id:null});combatMessage=target?'Impacto no '+target.name+' ? dano '+weaponSystem.damage:'Disparo efetuado ? nenhum alvo travado';refreshStationMarket();savePosition()}
function destroyAsteroid(id){if(destroyedAsteroids.has(id))return;window.gameAudio?.play('explosion_small');destroyedAsteroids.add(id);let reward=Math.min(missionSystem.remainingMaterialCapacity(),2+Math.floor(Math.random()*5));if(reward>0){miningState.oreCounts.Ferro+=reward;miningState.ore+=reward;miningState.status='Fragmentos recuperados: +'+reward+' kg de ferro'}else miningState.status='Asteroide fragmentado ? compartimento cheio';let option=Array.from(bodySelect.options).find(o=>o.value===id);if(option)option.disabled=true;if(selected.id===id){selected=bodies.find(b=>b.id==='aurora')}combatMessage='Asteroide fragmentado ? ferro recuperado +'+reward+' kg';if(stationScreen.classList.contains('open'))refreshStationMarket();savePosition()}
