// Detailed orbital station renderer. This later declaration replaces the compact prototype above.
function drawStation(b,p){
    const time=performance.now()/1000;
    const scale=Math.min(.84,Math.max(.025,p.r/108));
    const bearing=Math.atan2(player.x-b.x,player.z-b.z);
    const ringX=-48,ringRX=78,ringRY=118;
    const pulse=.72+Math.sin(time*3.1)*.28;
    ctx.save();
    ctx.translate(p.x,p.y+Math.sin(time*.55)*1.6);
    ctx.rotate(-.105+Math.sin(time*.28)*.008);
    ctx.scale(scale,scale*.94);ctx.transform(1,Math.sin(bearing)*.22,0,1,0,0);
    ctx.lineCap='round';
    ctx.lineJoin='round';

    function rounded(x,y,w,h,r,fill,stroke='#9cb8bd',line=1.4){
        ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();
        if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=line;ctx.stroke()}
    }
    function beacon(x,y,color='#ffc775',size=2.5,phase=0){
        const glow=.55+.45*Math.sin(time*3.4+phase);
        ctx.save();ctx.globalAlpha=.55+glow*.45;ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=7+glow*8;
        ctx.beginPath();ctx.arc(x,y,size+glow*.6,0,Math.PI*2);ctx.fill();ctx.restore();
    }
    function truss(x1,y1,x2,y2,width=9){
        const dx=x2-x1,dy=y2-y1,len=Math.hypot(dx,dy),a=Math.atan2(dy,dx);
        ctx.save();ctx.translate(x1,y1);ctx.rotate(a);
        ctx.strokeStyle='#75939b';ctx.lineWidth=1.2;ctx.strokeRect(0,-width/2,len,width);
        ctx.beginPath();ctx.moveTo(0,-width/2);ctx.lineTo(len,width/2);ctx.moveTo(0,width/2);ctx.lineTo(len,-width/2);
        for(let x=18;x<len;x+=18){ctx.moveTo(x,-width/2);ctx.lineTo(x,width/2)}ctx.stroke();ctx.restore();
    }
    function panel(x,y,w,h,angle=0){
        ctx.save();ctx.translate(x,y);ctx.rotate(angle);
        ctx.shadowColor='rgba(33,150,225,.35)';ctx.shadowBlur=8;
        const pg=ctx.createLinearGradient(-w/2,-h/2,w/2,h/2);
        pg.addColorStop(0,'#06162c');pg.addColorStop(.45,'#0b3b68');pg.addColorStop(1,'#071d36');
        ctx.fillStyle=pg;ctx.strokeStyle='#77bad4';ctx.lineWidth=1.5;ctx.fillRect(-w/2,-h/2,w,h);ctx.strokeRect(-w/2,-h/2,w,h);
        ctx.shadowBlur=0;ctx.strokeStyle='rgba(89,168,211,.65)';ctx.lineWidth=.8;
        for(let i=1;i<6;i++){let px=-w/2+w*i/6;ctx.beginPath();ctx.moveTo(px,-h/2);ctx.lineTo(px,h/2);ctx.stroke()}
        for(let i=1;i<9;i++){let py=-h/2+h*i/9;ctx.beginPath();ctx.moveTo(-w/2,py);ctx.lineTo(w/2,py);ctx.stroke()}
        const shine=ctx.createLinearGradient(-w/2,0,w/2,0);shine.addColorStop(0,'transparent');shine.addColorStop(.45,'rgba(140,225,255,.18)');shine.addColorStop(.58,'transparent');
        ctx.fillStyle=shine;ctx.fillRect(-w/2,-h/2,w,h);ctx.restore();
    }
    function cylinder(x,y,w,h,colors=['#213f4c','#4e7180','#162f3d']){
        ctx.save();
        ctx.shadowColor='rgba(0,0,0,.7)';ctx.shadowBlur=8;ctx.shadowOffsetY=5;
        const cg=ctx.createLinearGradient(0,y-h/2,0,y+h/2);cg.addColorStop(0,colors[1]);cg.addColorStop(.24,colors[0]);cg.addColorStop(.72,colors[2]);cg.addColorStop(1,'#0a1822');
        rounded(x,y-h/2,w,h,h*.28,cg,'#a8c5c5',1.7);ctx.shadowBlur=0;ctx.shadowOffsetY=0;
        ctx.fillStyle='rgba(218,239,233,.28)';ctx.beginPath();ctx.ellipse(x+w-3,y,h*.16,h*.38,0,0,Math.PI*2);ctx.fill();
        ctx.strokeStyle='rgba(155,205,207,.55)';ctx.lineWidth=1;
        for(let px=x+18;px<x+w-12;px+=23){ctx.beginPath();ctx.moveTo(px,y-h*.38);ctx.lineTo(px,y+h*.38);ctx.stroke()}
        ctx.restore();
    }

    // Soft silhouette makes the structure readable against bright stars.
    ctx.save();ctx.globalAlpha=.32;ctx.shadowColor='#43cce6';ctx.shadowBlur=30;ctx.strokeStyle='#183e50';ctx.lineWidth=21;
    ctx.beginPath();ctx.ellipse(ringX,0,ringRX,ringRY,0,0,Math.PI*2);ctx.stroke();ctx.restore();

    // Rear ring, with an animated internal wheel.
    const ringMetal=ctx.createLinearGradient(ringX-ringRX,-ringRY,ringX+ringRX,ringRY);
    ringMetal.addColorStop(0,'#294d5b');ringMetal.addColorStop(.2,'#d2e1d9');ringMetal.addColorStop(.43,'#537884');ringMetal.addColorStop(.7,'#b7ccc7');ringMetal.addColorStop(1,'#233e4c');
    ctx.strokeStyle='#102834';ctx.lineWidth=22;ctx.beginPath();ctx.ellipse(ringX,0,ringRX,ringRY,0,0,Math.PI*2);ctx.stroke();
    ctx.strokeStyle=ringMetal;ctx.lineWidth=15;ctx.beginPath();ctx.ellipse(ringX,0,ringRX,ringRY,0,0,Math.PI*2);ctx.stroke();
    ctx.strokeStyle='rgba(116,226,234,.8)';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(ringX,0,ringRX-10,ringRY-12,0,0,Math.PI*2);ctx.stroke();
    for(let i=0;i<14;i++){
        const a=i*Math.PI/7+time*.12;
        const ox=ringX+Math.cos(a)*(ringRX-12),oy=Math.sin(a)*(ringRY-15);
        const ix=ringX+Math.cos(a)*30,iy=Math.sin(a)*43;
        ctx.strokeStyle=i%2?'rgba(172,194,190,.72)':'rgba(95,151,160,.72)';ctx.lineWidth=i%2?3.2:2.2;
        ctx.beginPath();ctx.moveTo(ix,iy);ctx.lineTo(ox,oy);ctx.stroke();
        ctx.save();ctx.translate(ox,oy);ctx.rotate(a+Math.PI/2);rounded(-7,-4,14,8,3,'#264b59','#b8d1ce',.8);ctx.restore();
    }

    // Rear solar wings and their articulated supports.
    truss(-176,-2,-120,-2,8);truss(112,-1,166,-73,7);truss(112,1,171,73,7);truss(248,0,305,-33,6);
    panel(-183,-2,49,106,-.17);panel(172,-91,40,77,.08);panel(179,91,40,77,-.08);panel(318,-39,78,29,-.07);

    // Long central spine and service pipes.
    ctx.strokeStyle='#759ba4';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-210,0);ctx.lineTo(349,0);ctx.stroke();
    ctx.strokeStyle='#d5e1dc';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(-209,-5);ctx.lineTo(348,-5);ctx.moveTo(-209,5);ctx.lineTo(348,5);ctx.stroke();
    ctx.strokeStyle='#397182';ctx.lineWidth=1;ctx.setLineDash([6,7]);ctx.beginPath();ctx.moveTo(-202,9);ctx.lineTo(338,9);ctx.stroke();ctx.setLineDash([]);

    // Habitat, laboratory and cargo sections.
    cylinder(-72,-1,116,51);
    cylinder(34,-1,176,43,['#173340','#496c7b','#102631']);
    cylinder(201,-1,69,31,['#203c48','#5b7b83','#132831']);
    cylinder(278,-1,62,37,['#273f47','#6f8990','#172832']);
    rounded(93,-29,37,17,6,'#173542','#9cbdbd',1.2);rounded(105,17,26,14,5,'#122d39','#91b6b8',1.1);
    for(let x of [-38,-18,2,22,55,78,151,219,294])beacon(x,-4,x===78?'#69fff0':'#ffc477',1.6,x*.13);

    // Central command hub and glass observation dome.
    const hub=ctx.createRadialGradient(ringX-10,-12,3,ringX,0,34);hub.addColorStop(0,'#8ba7aa');hub.addColorStop(.45,'#294d58');hub.addColorStop(1,'#0b1d28');
    ctx.fillStyle=hub;ctx.strokeStyle='#d4e5df';ctx.lineWidth=3;ctx.beginPath();ctx.arc(ringX,0,33,0,Math.PI*2);ctx.fill();ctx.stroke();
    const glass=ctx.createRadialGradient(ringX-9,-10,1,ringX,0,22);glass.addColorStop(0,'#d8ffff');glass.addColorStop(.18,'#65dadc');glass.addColorStop(.58,'#0d4559');glass.addColorStop(1,'#04131e');
    ctx.fillStyle=glass;ctx.strokeStyle='#8ef4ee';ctx.lineWidth=2;ctx.beginPath();ctx.arc(ringX,0,21,0,Math.PI*2);ctx.fill();ctx.stroke();
    ctx.save();ctx.globalAlpha=pulse;ctx.shadowColor='#8cfff4';ctx.shadowBlur=22;ctx.fillStyle='#bafff5';ctx.beginPath();ctx.arc(ringX,0,5.5+pulse,0,Math.PI*2);ctx.fill();ctx.restore();

    // Docking collar, antenna and forward navigation mast.
    rounded(333,-12,42,24,9,'#1b3540','#bdd1cc',1.7);ctx.strokeStyle='#557b84';ctx.lineWidth=2;
    ctx.beginPath();ctx.ellipse(374,0,7,12,0,0,Math.PI*2);ctx.stroke();
    ctx.beginPath();ctx.moveTo(353,-15);ctx.lineTo(373,-31);ctx.moveTo(357,15);ctx.lineTo(380,28);ctx.stroke();
    ctx.strokeStyle='#9bb8b8';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(145,-22);ctx.lineTo(145,-53);ctx.stroke();
    ctx.strokeStyle='#82bec8';ctx.lineWidth=2;ctx.beginPath();ctx.arc(145,-48,17,Math.PI,Math.PI*2);ctx.stroke();beacon(145,-54,'#70eaff',2,1);
    for(let x of [-209,-143,188,258,345])beacon(x,0,'#ffbd64',2,x*.09);

    // Front highlight gives the ring a thick, layered torus appearance.
    ctx.strokeStyle='rgba(233,246,237,.72)';ctx.lineWidth=3.2;ctx.beginPath();ctx.ellipse(ringX,0,ringRX,ringRY,0,.12*Math.PI,.88*Math.PI);ctx.stroke();
    ctx.strokeStyle='rgba(4,16,25,.52)';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(ringX,0,ringRX,ringRY,0,1.08*Math.PI,1.9*Math.PI);ctx.stroke();
    ctx.restore();

    if(p.r>8){
        const labelY=p.y+Math.min(p.r*.93,ringRY*scale+25);
        ctx.save();ctx.textAlign='center';ctx.font='10px Space Mono';ctx.fillStyle='#d9f7f6';ctx.shadowColor='#020711';ctx.shadowBlur=7;
        ctx.fillText('PORTO AURORA',p.x,labelY);ctx.font='7px Space Mono';ctx.fillStyle='rgba(129,205,215,.78)';ctx.fillText('ESTAÃ‡ÃƒO ORBITAL ? DOCA 04',p.x,labelY+13);ctx.restore();
    }
}

function drawStation3DModel(body,p){
    const design=Number(body.design)||0,time=performance.now()/1000;
    const scale=design===2?Math.min(1.15,Math.max(.035,p.r/145)):Math.min(.9,Math.max(.018,p.r/220));
