    const sideParallax=Math.sin(bearing)*.22;
    ctx.save();ctx.translate(p.x,p.y+Math.sin(t*.7+style)*1.5);ctx.rotate(Math.sin(t*.22+style)*.018);ctx.scale(scale*1.12,scale*.94);ctx.transform(1,sideParallax,0,1,0,0);
