// Com?rcio das estaÃ§Ãµes: ferro minerado vira cr?ditos; armas e recargas usam o saldo.
function refreshStationMarket(){
  const iron=miningState.oreCounts.Ferro||0;
  document.querySelector('#stationIron').innerHTML=iron+' <small>kg</small>';
  document.querySelector('#stationNickel').innerHTML=(miningState.oreCounts.Niquel||0)+' <small>kg</small>';
  document.querySelector('#stationCobalt').innerHTML=(miningState.oreCounts.Cobalto||0)+' <small>kg</small>';
  document.querySelector('#stationAmmo').innerHTML=weaponSystem.ammo+' <small>/ '+weaponSystem.maxAmmo+'</small>';
  document.querySelector('#stationCredits').innerHTML=credits+' <small>CR</small>';document.querySelectorAll('[data-buy-ship]').forEach(button=>{const spec=shipModels[button.dataset.buyShip];button.disabled=button.dataset.buyShip===shipClass});document.querySelector('#stationFuelValue').textContent=fuelUnits.toLocaleString('pt-BR',{maximumFractionDigits:0})+' / '+fuelCapacityUnits.toLocaleString('pt-BR')+' U';document.querySelector('#stationFuelSpace').textContent=Math.round(fuelCargoWeight()).toLocaleString('pt-BR')+' kg no compartimento';document.querySelector('#fuelMarketNote').textContent='Alcance restante: '+Math.floor(fuelUnits*700).toLocaleString('pt-BR')+' km';document.querySelectorAll('[data-refuel]').forEach(button=>{const want=button.dataset.refuel==='fill'?fuelCapacityUnits-fuelUnits:Number(button.dataset.refuel);button.disabled=want<=0||!stationIds.includes(selected.id)||dist3(player,selected)>2200||window.crewRole==='copilot'});
  stationSale.refreshUI();
  document.querySelector('#stationWeaponStatus').textContent=weaponSystem.installed?weaponLabel(weaponSystem.kind)+' ? '+weaponSystem.damage+' DMG':'sem armamento';
  document.querySelector('#cannonDamage').textContent=weaponSystem.damage;
  document.querySelector('#cannonStatus').textContent=weaponSystem.owned.includes('pulse')?(weaponSystem.kind==='pulse'?'EQUIPADO':'ADQUIRIDO'):'NÃƒO ADQUIRIDO';
  document.querySelector('#ammoDetail').textContent=weaponSystem.ammo+' / '+weaponSystem.maxAmmo;
  document.querySelector('#stationAmmoBar').style.width=(weaponSystem.ammo/weaponSystem.maxAmmo*100)+'%';
  const owned=weaponSystem.owned;
  const pulse=document.querySelector('#buyCannon'),ammo=document.querySelector('#buyAmmo'),upgrade=document.querySelector('#buyUpgrade');
  pulse.disabled=shipClass==='freighter'||(credits<120&&!owned.includes('pulse'));pulse.textContent=owned.includes('pulse')?(weaponSystem.kind==='pulse'?'PULSO EQUIPADO':'EQUIPAR PULSO ?'):'ADQUIRIR ? 120 CR ?';
  ammo.disabled=shipClass==='freighter'||!weaponSystem.installed||weaponSystem.ammo>=weaponSystem.maxAmmo;ammo.textContent='CARREGAR +30 ? 30 CR ?';
  upgrade.disabled=shipClass==='freighter'||!owned.includes('pulse')||weaponSystem.kind!=='pulse'||weaponSystem.damage>=10;upgrade.textContent=weaponSystem.damage>=10&&owned.includes('pulse')?'UPGRADE INSTALADO':'MELHORAR ? 80 CR ?';
  for(const [kind,id,statusId] of [['ion','buyIon','ionStatus'],['heavy','buyHeavy','heavyStatus']]){const button=document.querySelector('#'+id);const isOwned=owned.includes(kind);document.querySelector('#'+statusId).textContent=isOwned?(weaponSystem.kind===kind?'EQUIPADO':'ADQUIRIDO'):'NAO ADQUIRIDO';button.disabled=shipClass==='freighter';button.textContent=isOwned?(weaponSystem.kind===kind?'EQUIPADO':'EQUIPAR ->'):'ADQUIRIR ->'}
  const siege=document.querySelector('#buySingularity'),siegeOwned=owned.includes('singularity');document.querySelector('#singularityStatus').textContent=siegeOwned?(weaponSystem.kind==='singularity'?'EQUIPADO':'ADQUIRIDO'):'NAO ADQUIRIDO';siege.disabled=shipClass==='freighter'||(siegeOwned&&weaponSystem.kind==='singularity');siege.textContent=siegeOwned?(weaponSystem.kind==='singularity'?'EQUIPADO':'EQUIPAR CANHAO ->'):'COMPRAR + 50.000 CR + MINERIOS'
}
function localShipSnapshot(id='local-'+Date.now()) { return {id,model:shipClass,name:shipModelName(),x:player.x,z:player.z,yaw:player.yaw,fuel:fuelUnits,hull:shipHull,cargo:{...miningState.oreCounts},weapon:{...weaponSystem,owned:[...weaponSystem.owned]}} }
function renderShipyard(fleet=localFleet) {
  const host=document.querySelector('#shipyardFleet'); if(!host)return;
  const catalog=host.closest('.shipyard').querySelector('.shipyard-products');
  catalog.querySelectorAll('[data-buy-ship]').forEach(button=>{const spec=shipModels[button.dataset.buyShip];button.disabled=(button.dataset.buyShip==='freighter')&&shipClass==='freighter';});
  if(!fleet.length) { host.innerHTML='<div class="social-empty">Sua nave atual esta no hangar; nenhuma outra nave cadastrada.</div>';return; }
  host.innerHTML=fleet.map(ship=>{const isCurrent=(multiplayerEnabled?!!ship.active:ship.model===shipClass&&ship.active===true),model=shipModels[ship.model]||shipModels.explorer,capacity=Number(ship.cargoCapacity||model.cargo),fuelCap=Number(ship.fuelCapacity||model.fuel),canActivate=multiplayerEnabled?!!ship.availableHere:ship.storedAt===selected.id;return `<div class="shipyard-vessel"><div class="shipyard-vessel-info">${socialEscape(ship.name||model.name)}${isCurrent?' / ATIVA':''}<small>${capacity.toLocaleString('pt-BR')} kg de carga / ${Number(ship.fuel||0).toLocaleString('pt-BR')}/${fuelCap.toLocaleString('pt-BR')} U de combustivel${ship.storedAt?' / HANGAR': ''}</small></div><button type="button" data-activate-ship="${String(ship.id||0)}" ${isCurrent||!canActivate?'disabled':''}>${isCurrent?'EM USO':'ATIVAR'}</button></div>`}).join('');
}
async function refreshShipyard() {
  if(!multiplayerEnabled){const current=localShipSnapshot('active');current.active=true;renderShipyard([current,...localFleet]);return}
  const host=document.querySelector('#shipyardFleet');host.innerHTML='<div class="social-empty">Consultando hangar...</div>';
  try{const data=await socialRequest('station-shipyard',null,'&station='+encodeURIComponent(selected.id));credits=Number(data.credits)||0;renderShipyard(data.fleet||[]);refreshStationMarket()}catch(error){host.innerHTML='<div class="social-empty">'+socialEscape(error.message)+'</div>'}
}
function saveCurrentLocalShip(){localFleet=localFleet.filter(ship=>ship.id!=='active');localFleet.push({...localShipSnapshot(String(localShipCounter++)),storedAt:selected.id});}
function createLocalShip(model){const spec=shipModels[model];setShipModel(model);player.x=selected.x;player.z=selected.z;player.yaw=0;player.speed=0;shipHull=spec.hull;fuelUnits=fuelCapacityUnits;miningState.oreCounts={Ferro:0,Niquel:0,Cobalto:0};miningState.ore=0;weaponSystem.installed=false;weaponSystem.owned=[];weaponSystem.kind='pulse';weaponSystem.ammo=0;weaponSystem.maxAmmo=90;weaponSystem.damage=5;weaponSystem.upgraded=false;if(model==='attack'){weaponSystem.kind='heavy';weaponSystem.owned=['heavy'];weaponSystem.installed=true;weaponSystem.ammo=90;weaponSystem.maxAmmo=90;weaponSystem.damage=Math.round(55*spec.damage)}}
stationScreen.querySelector('.shipyard').addEventListener('click',async event=>{
  const buy=event.target.closest('[data-buy-ship]'),activate=event.target.closest('[data-activate-ship]');if(!buy&&!activate)return;
  const button=buy||activate;if(button.disabled)return;button.disabled=true;
  try{
    if(buy){const model=buy.dataset.buyShip,spec=shipModels[model];if(credits<spec.price)throw new Error(insufficientCreditsMessage(spec.price));if(multiplayerEnabled){await socialRequest('station-ship-purchase',{station:selected.id,model});await window.crewGame.refreshShip()}else{credits-=spec.price;saveCurrentLocalShip();createLocalShip(model);savePosition();updateHud()}setStationMessage(spec.name+' adquirida. Sua nave anterior ficou guardada nesta estacao.');}
    else {const id=activate.dataset.activateShip;if(multiplayerEnabled){await socialRequest('station-ship-activate',{station:selected.id,ship_id:id});await window.crewGame.refreshShip()}else{const old=localFleet.find(ship=>String(ship.id)===String(id));if(!old)throw new Error('Nave guardada nao encontrada.');const current=localShipSnapshot('active');Object.assign(player,{x:Number(old.x)||selected.x,z:Number(old.z)||selected.z,yaw:Number(old.yaw)||0,speed:0});setShipModel(old.model);fuelUnits=Math.min(fuelCapacityUnits,Number(old.fuel)||0);shipHull=Number(old.hull)||100;miningState.oreCounts=old.cargo||{Ferro:0,Niquel:0,Cobalto:0};miningState.ore=Object.values(miningState.oreCounts).reduce((a,b)=>a+Number(b||0),0);Object.assign(weaponSystem,old.weapon||{});localFleet=localFleet.filter(ship=>ship!==old);localFleet.push({...current,id:String(localShipCounter++),storedAt:selected.id});savePosition();updateHud()}setStationMessage('Nave selecionada e trazida para a baia.');}
    await refreshShipyard();refreshStationMarket();updateHud();savePosition();
  }catch(error){setStationMessage(error.message||'Nao foi possivel concluir a troca de nave.');button.disabled=false}
});
function weaponLabel(kind){return kind==='singularity'?'CANHAO DE SINGULARIDADE':kind==='ion'?'CANHAO DE IONS':kind==='heavy'?'CANHAO DE PLASMA':'CANHAO DE PULSO'}
function openStationMarket(body){targetManuallyChosen=true;stationAutoTargetId=null;stationAutoPrevious=null;selected=body;autopilot=false;orbitMode=false;player.speed=0;stationBank.open(body.id);stationSale.open(body.id);stationBrand.textContent=body.name.toUpperCase();stationMark.textContent=body.name.trim().charAt(0).toUpperCase();stationScreen.querySelector('.station-brand small').textContent='MERCADO ORBITAL ? '+String(body.id).toUpperCase();stationScreen.querySelector('.station-footer span:first-child').innerHTML=body.name.toUpperCase()+' <b>?</b> ARMARIA CERTIFICADA';missionSystem.openAt(body);stationScreen.classList.add('open');stationScreen.setAttribute('aria-hidden','false');refreshShipyard();setStationMessage('Terminal de '+body.name+' conectado. Consulte contratos, venda ferro ou negocie equipamento.');refreshStationMarket()}
window.openStationMarket=openStationMarket;
function equipWeapon(kind){const profile={pulse:{damage:5,maxAmmo:90},ion:{damage:25,maxAmmo:90},heavy:{damage:55,maxAmmo:90},singularity:{damage:150,maxAmmo:30}}[kind];if(!profile)return;const oreLoad=Object.values(miningState.oreCounts).reduce((sum,value)=>sum+(Number(value)||0),0),mountWeight=weaponMountWeights[kind]||0;if(oreLoad+mountWeight+mountedTowWeight()+fuelCargoWeight()+passengerCargoWeight()>cargoCapacityKg){setStationMessage('A arma pesa '+mountWeight+' kg. Desocupe carga antes de instalar.');return}weaponSystem.kind=kind;weaponSystem.weightKg=mountWeight;weaponSystem.owned=Array.from(new Set([...weaponSystem.owned,kind]));weaponSystem.installed=true;weaponSystem.damage=Math.round((kind==='pulse'&&weaponSystem.upgraded?10:profile.damage)*(shipClass==='attack'?1.35:1));weaponSystem.maxAmmo=profile.maxAmmo;weaponSystem.installed=true;combatMessage=weaponLabel(kind)+' equipado';setStationMessage(weaponLabel(kind)+' equipado na nave.');refreshStationMarket();savePosition();return true}
function purchaseWeapon(kind,price){if(weaponSystem.owned.includes(kind)){equipWeapon(kind);return}if(credits<price){setStationMessage(insufficientCreditsMessage(price));return}const mass=weaponMountWeights[kind]||0,load=Object.values(miningState.oreCounts).reduce((sum,value)=>sum+(Number(value)||0),0);if(load+mass+fuelCargoWeight()+passengerCargoWeight()>cargoCapacityKg){setStationMessage('O canhao ocupa '+mass+' kg. Libere espaco antes de instalar.');return}credits-=price;if(!equipWeapon(kind))return;setStationMessage(weaponLabel(kind)+' adquirido e equipado.');savePosition();}
for(const id of ['buyCannon','buyAmmo','buyUpgrade','buyIon','buyHeavy'])document.querySelector('#'+id).addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();const button=event.currentTarget;if(button.disabled)return;if(id==='buyCannon'){purchaseWeapon('pulse',120)}else if(id==='buyIon'){purchaseWeapon('ion',260)}else if(id==='buyHeavy'){purchaseWeapon('heavy',500)}else if(id==='buyAmmo'){if(!weaponSystem.installed)return;if(credits<30){setStationMessage(insufficientCreditsMessage(30));return}credits-=30;const charge=Math.min(30,weaponSystem.maxAmmo-weaponSystem.ammo);weaponSystem.ammo+=charge;setStationMessage('Recarga conclu?da: +'+charge+' c?lulas de plasma.');refreshStationMarket();savePosition()}else if(id==='buyUpgrade'){if(credits<80){setStationMessage(insufficientCreditsMessage(80));return}credits-=80;weaponSystem.upgraded=true;weaponSystem.damage=10;setStationMessage('Capacitor MK-II instalado. Dano do canhÃ£o de pulso elevado para 42.');refreshStationMarket();savePosition()}},true);
