canvas.addEventListener('click',event=>{if(!multiplayerEnabled)return;const rect=canvas.getBoundingClientRect(),mx=(event.clientX-rect.left)*W/rect.width,my=(event.clientY-rect.top)*H/rect.height;let found=null,best=Infinity;for(const ship of remoteShips){const info=remoteShipRenderInfo(ship);if(!info)continue;const px=info.mode==='ship'?info.point.x:info.x,py=info.mode==='ship'?info.point.y:info.y,radius=info.mode==='ship'?Math.max(30,clamp(48000/info.point.z,16,29)*2.35):27,distance=Math.hypot(mx-px,my-py);if(distance<radius&&distance<best){best=distance;found=ship}}if(found){combatTargetId=Number(found.id);const rescueButton=document.querySelector('#profileTowAction');if(rescueButton){const needsRescue=Number(found.fuel)<=0&&Number(found.hull)>0;rescueButton.hidden=!needsRescue;rescueButton.disabled=false;rescueButton.textContent='SOLICITAR REBOQUE';}openPilotProfile(found.id);return}const wreckHit=lootDrops.map(wreck=>({wreck,point:project({x:wreck.x,y:0,z:wreck.z,r:30})})).filter(item=>item.point&&Math.hypot(mx-item.point.x,my-item.point.y)<Math.max(22,item.point.r+12)).sort((a,b)=>Math.hypot(mx-a.point.x,my-a.point.y)-Math.hypot(mx-b.point.x,my-b.point.y))[0];if(wreckHit)openWreck(wreckHit.wreck)});
function setCallView(title,status,mode='active'){document.querySelector('#callTitle').textContent=title;document.querySelector('#callStatus').textContent=status;document.querySelector('#callAccept').style.display=mode==='incoming'?'':'none';document.querySelector('#callDecline').style.display=mode==='incoming'?'':'none';document.querySelector('#callHangup').style.display=mode==='incoming'?'none':'';callOverlay.classList.add('open');callOverlay.setAttribute('aria-hidden','false')}
function closeCallView(){callOverlay.classList.remove('open');callOverlay.setAttribute('aria-hidden','true')}
async function postCallControl(action){if(!activeCallId)return;try{await socialRequest(action,{call_id:activeCallId})}catch(error){}}
function stopVoiceMedia(){if(callPeerConnection){callPeerConnection.onicecandidate=null;callPeerConnection.ontrack=null;callPeerConnection.close();callPeerConnection=null}if(callLocalStream){callLocalStream.getTracks().forEach(track=>track.stop());callLocalStream=null}document.querySelector('#remoteCallAudio').srcObject=null;pendingCallOffer=null;pendingCallIce=[]}
async function endVoiceCall(notify=true,message='LigaÃ§Ã£o encerrada.'){const callId=activeCallId;if(notify)await postCallControl('call-end');if(callId)callSocket?.notify(callId);stopVoiceMedia();activeCallId='';callRole='';callAccepted=false;callPeerId=0;setCallView('CHAMADA DE VOZ',message,'done');setTimeout(closeCallView,1800)}
async function sendCallSignal(type,payload){if(!activeCallId)return;try{if(!callSocket?.signal(activeCallId,type,payload))await socialRequest('call-signal',{call_id:activeCallId,type,payload})}catch(error){document.querySelector('#callStatus').textContent=error.message}}
async function flushCallIce(){if(!callPeerConnection?.remoteDescription)return;for(const candidate of pendingCallIce.splice(0)){try{await callPeerConnection.addIceCandidate(new RTCIceCandidate(candidate))}catch(error){}}}
async function setupVoicePeer(){if(callPeerConnection)return;callLocalStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});callPeerConnection=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});for(const track of callLocalStream.getTracks())callPeerConnection.addTrack(track,callLocalStream);callPeerConnection.onicecandidate=event=>{if(event.candidate)sendCallSignal('ice',event.candidate.toJSON())};callPeerConnection.ontrack=event=>{const audio=document.querySelector('#remoteCallAudio');audio.srcObject=event.streams[0];audio.play().catch(()=>{})};callPeerConnection.onconnectionstatechange=()=>{if(callPeerConnection&&['failed','closed'].includes(callPeerConnection.connectionState))endVoiceCall(true,'A conexÃ£o de voz foi interrompida.')}}
async function startVoiceCall(userId,name){try{const data=await socialRequest('call-start',{user_id:userId});activeCallId=data.call_id;callRole='caller';callPeerId=userId;callPeerName=name;callAccepted=false;callSocket?.ring(activeCallId);setCallView('CHAMANDO '+name.toUpperCase(),'Aguardando o piloto atenderâ€¦');await setupVoicePeer();const offer=await callPeerConnection.createOffer();await callPeerConnection.setLocalDescription(offer);await sendCallSignal('offer',callPeerConnection.localDescription.toJSON())}catch(error){if(activeCallId)await postCallControl('call-end');stopVoiceMedia();activeCallId='';setCallView('CHAMADA NÃƒO INICIADA',error.message,'done');setTimeout(closeCallView,2600)}}
async function acceptVoiceCall(){try{await socialRequest('call-accept',{call_id:activeCallId});callSocket?.notify(activeCallId);callAccepted=true;setCallView('LIGAÃ‡ÃƒO COM '+callPeerName.toUpperCase(),'Conectando o Ã¡udioâ€¦');await setupVoicePeer();if(pendingCallOffer)await answerIncomingOffer()}catch(error){await postCallControl('call-end');stopVoiceMedia();activeCallId='';callRole='';setCallView('ERRO NA LIGAÃ‡ÃƒO',error.message,'done');setTimeout(closeCallView,2600)}}
async function answerIncomingOffer(){if(!callPeerConnection||!pendingCallOffer||callPeerConnection.remoteDescription)return;await callPeerConnection.setRemoteDescription(new RTCSessionDescription(pendingCallOffer));await flushCallIce();const answer=await callPeerConnection.createAnswer();await callPeerConnection.setLocalDescription(answer);await sendCallSignal('answer',callPeerConnection.localDescription.toJSON());pendingCallOffer=null;setCallView('LIGAÃ‡ÃƒO COM '+callPeerName.toUpperCase(),'Microfone conectado ? chamada de voz ativa.')}
async function handleCallSignal(signal){if(signal.call_id!==activeCallId)return;try{if(signal.signal_type==='offer'){pendingCallOffer=signal.payload;if(callRole==='callee'&&callAccepted)await answerIncomingOffer()}else if(signal.signal_type==='answer'&&callRole==='caller'&&callPeerConnection&&!callPeerConnection.remoteDescription){await callPeerConnection.setRemoteDescription(new RTCSessionDescription(signal.payload));await flushCallIce();setCallView('LIGAÃ‡ÃƒO COM '+callPeerName.toUpperCase(),'Microfone conectado ? chamada de voz ativa.')}else if(signal.signal_type==='ice'){if(callPeerConnection?.remoteDescription)await callPeerConnection.addIceCandidate(new RTCIceCandidate(signal.payload));else pendingCallIce.push(signal.payload)}}catch(error){document.querySelector('#callStatus').textContent='Falha na conexÃ£o de Ã¡udio: '+error.message}}
callSocket=window.createCallSocket({api:multiplayerApi,enabled:multiplayerEnabled,onEvent:async event=>{if(event.type==='call_invite'&&!activeCallId){activeCallId=String(event.callId);callRole='callee';callAccepted=false;callPeerId=Number(event.callerId);callPeerName=String(event.callerName||'PILOTO');setCallView('CHAMADA DE '+callPeerName.toUpperCase(),'Quer atender esta chamada de voz?','incoming')}else if(event.type==='call_state'&&event.callId===activeCallId){if(event.status==='accepted'&&callRole==='caller'){callAccepted=true;document.querySelector('#callStatus').textContent='Piloto atendeu ? conectando Ã¡udioâ€¦'}else if(['declined','missed','ended'].includes(event.status)){endVoiceCall(false,event.status==='declined'?'O piloto recusou a ligaÃ§Ã£o.':event.status==='missed'?'O piloto nÃ£o atendeu.':'A ligaÃ§Ã£o foi encerrada pelo outro piloto.')}}else if(event.type==='signal'){await handleCallSignal({call_id:String(event.callId),signal_type:event.signalType,payload:event.payload})}}});
document.querySelector('#callAccept').addEventListener('click',acceptVoiceCall);document.querySelector('#callDecline').addEventListener('click',async()=>{const callId=activeCallId;await postCallControl('call-decline');if(callId)callSocket?.notify(callId);stopVoiceMedia();activeCallId='';callRole='';closeCallView()});document.querySelector('#callHangup').addEventListener('click',()=>endVoiceCall(true));
let lastCallPollBusy=false;async function pollCalls(){if(!multiplayerEnabled||lastCallPollBusy)return;lastCallPollBusy=true;try{const data=await socialRequest('call-poll');for(const call of data.calls||[]){const id=String(call.call_id),isCaller=Number(call.caller_id)===multiplayerUserId;if(activeCallId&&id===activeCallId){if(call.status==='accepted'&&callRole==='caller'){callAccepted=true;document.querySelector('#callStatus').textContent='Piloto atendeu ? conectando Ã¡udioâ€¦'}else if(['declined','missed','ended'].includes(call.status)){endVoiceCall(false,call.status==='declined'?'O piloto recusou a ligaÃ§Ã£o.':call.status==='missed'?'O piloto nÃ£o atendeu.':'A ligaÃ§Ã£o foi encerrada pelo outro piloto.')}}else if(!activeCallId&&call.status==='ringing'&&!isCaller){activeCallId=id;callRole='callee';callAccepted=false;callPeerId=Number(call.caller_id);callPeerName=call.caller_name;setCallView('CHAMADA DE '+String(call.caller_name).toUpperCase(),'Quer atender esta chamada de voz?','incoming')}}for(const signal of data.signals||[])await handleCallSignal(signal)}catch(error){}finally{lastCallPollBusy=false}}
