const jettisonStyle=document.createElement('style');jettisonStyle.textContent=`.jettison-overlay{position:fixed;inset:0;z-index:62;display:none;place-items:center;padding:18px;background:rgba(1,7,15,.85);backdrop-filter:blur(9px)}.jettison-overlay.open{display:grid}.jettison-card{width:min(440px,94vw);padding:20px;background:linear-gradient(145deg,#102633,#07131e);border:1px solid rgba(255,183,121,.48);box-shadow:0 0 45px rgba(255,139,67,.15)}.jettison-card h2{margin:6px 0 8px;font-size:25px;font-weight:500}.jettison-copy,.jettison-status{color:#97b0b6;font-size:13px;line-height:1.45}.jettison-row{display:grid;grid-template-columns:1fr 90px;gap:8px;align-items:center;margin:8px 0;padding:9px;border:1px solid rgba(120,180,190,.16);background:#091923;color:#d1e7e8;font:9px 'Space Mono'}.jettison-row small{display:block;margin-top:4px;color:#769ba5;font-size:7px}.jettison-row input{width:100%;padding:8px;background:#06121b;color:#f1fbfa;border:1px solid rgba(116,196,205,.3);font:10px 'Space Mono'}.jettison-actions{display:flex;gap:8px;margin-top:12px}.jettison-actions button{flex:1;padding:10px;border:1px solid rgba(120,195,204,.32);background:#0a2330;color:#c2ebeb;font:8px 'Space Mono';cursor:pointer}.jettison-actions button.primary{border-color:#e5a76e;color:#ffe0bf;background:rgba(115,61,31,.3)}.jettison-actions button:disabled{opacity:.45}@media(max-width:480px){.jettison-card{padding:15px}}`;document.head.appendChild(jettisonStyle);document.body.insertAdjacentHTML('beforeend',`<div class="jettison-overlay" id="jettisonOverlay" aria-hidden="true"><section class="jettison-card" role="dialog" aria-modal="true"><div class="eyebrow">LIBERAÃ‡ÃƒO DE CARGA / SETOR ABERTO</div><h2>Descartar min?rio no espaÃ§o</h2><p class="jettison-copy">O contÃªiner ficarÃ¡ vis?vel para outros pilotos por at? 1 hora. Quem encontrar poderÃ¡ recolher os minerais se houver espaÃ§o na nave.</p><label class="jettison-row"><span>MinÃ©rio de ferro <small id="dropAvailIron">0 kg dispon?veis</smal