const jettisonOverlay=document.querySelector('#jettisonOverlay');function closeJettison(){jettisonOverlay.classList.remove('open');jettisonOverlay.setAttribute('aria-hidden','true')}function openJettisonModal(){if(!multiplayerEnabled){combatMessage='Entre no multiplayer para compartilhar carga com outros pilotos.';return}if(window.crewDocked||shipHull<=0){document.querySelector('#jettisonStatus').textContent=window.crewDocked?'Desacople a nave para liberar carga no espaÃ§o.':'Sua nave precisa estar operacional.';jettisonOverlay.classList.add('open');jettisonOverlay.setAttribute('aria-hidden','false');return}document.querySelector('#dropAvailIron').textContent=(Number(miningState.oreCounts.Ferro)||0).toLocaleString('pt-BR')+' kg dispon?veis';document.querySelector('#dropAvailNickel').textContent=(Number(miningState.oreCounts.Niquel)||0).toLocaleString('pt-BR')+' kg dispon?veis';document.querySelector('#dropAvailCobalt').textContent=(Number(miningState.oreCounts.Cobalto)||0).toLocaleString('pt-BR')+' kg dispon?veis';for(const id of ['dropIron','dropNickel','dropCobalt'])document.getElementById(id).value='0';document.querySelector('#jettisonStatus').textContent='O contÃªiner aparecerÃ¡ no local da sua nave.';jettisonOverlay.classList.add('open');jettisonOverlay.setAttribute('aria-hidden','false')}document.querySelector('#jettisonClose').addEventListener('click',closeJettison);jettisonOverlay.addEventListener('click',event=>{if(event.target===jettisonOverlay)closeJettison()});document.querySelector('#jettisonConfirm').addEventListener('click',async()=>{const button=document.querySelector('#jettisonConfirm'),cargo={Ferro:Math.max(0,Math.floor(Number(document.querySelector('#dropIron').value)||0)),Niquel:Math.max(0,Math.floor(Number(document.querySelector('#dropNickel').value)||0)),Cobalto:Math.max(0,Math.floor(Number(document.querySelector('#dropCobalt').value)||0))};button.disabled=true;try{const result=await socialRequest('cargo-jettison',{cargo});for(const [mineral,amount] of Object.entries(result.cargo||{}))miningState.oreCounts[mineral]=Math.max(0,(Number(miningState.oreCounts[mineral])||0)-Number(amount));miningState.ore=Object.values(miningState.oreCounts).reduce((sum,value)=>sum+value,0);combatMessage='ContÃªiner de min?rio liberado ? outros jogadores poderÃ£o encontrÃ¡-lo por 1 hora.';savePosition();await pollCombatWorld();closeJettison()}catch(error){document.querySelector('#jettisonStatus').textContent=error.message}finally{button.disabled=false}});

function closeWreck(){wreckOverlay.classList.remove('open');wreckOverlay.setAttribute('aria-hidden','true');selectedWreck=null} function openWreck(wreck){selectedWreck=wreck;const jettison=wreck.dropType==='jettison';document.querySelector('#wreckTitle').textContent=jettison?'ContÃªiner de carga':'DestroÃ§os da nave';document.querySelector('#wreckOwner').textContent=(jettison?'Carga liberada por ':'Carga abandonada por ')+String(wreck.username||'piloto').toUpperCase();document.querySelector('#wreckIron').textContent=Number(wreck.iron).toLocaleString('pt-BR')+' kg';document.querySelector('#wreckOther').textContent=(Number(wreck.nickel)+Number(wreck.cobalt)).toLocaleString('pt-BR')+' kg';document.querySelector('#wreckEnergy').textContent=Number(wreck.energy).toLocaleString('pt-BR')+' UE';const distance=Math.hypot(player.x-wreck.x,player.z-wreck.z);document.querySelector('#wreckDistance').textContent=fmt(distance)+' km';window.tractorSystem?.showWreck(wreck,distance);const capacity=Math.max(0,cargoCapacityKg-Object.values(miningState.oreCounts).reduce((sum,value)=>sum+(Number(value)||0),0)-mountedWeaponWeight()-mountedTowWeight()-fuelCargoWeight()-passengerCargoWeight()),hasMinerals=Number(wreck.iron)+Number(wreck.nickel)+Number(wreck.cobalt)>0;let expiry='';if(jettison&&wreck.expiresAt){const expires=new Date(String(wreck.expiresAt).replace(' ','T'));if(!Number.isNaN(expires.getTime()))expiry=' ? expira em '+Math.max(0,Math.ceil((expires.getTime()-Date.now())/60000))+' min'}document.querySelector('#wreckMessage').textContent=distance>1800?'Aproxime-se at? 1.800 km para coletar.':hasMinerals&&capacity<1?'Compartimento de carga cheio. Libere espaÃ§o para coletar.':'Carga ao alcance. Minerais respeitam o limite de carga.'+expiry;document.querySelector('#wreckCollect').disabled=distance>1800||(hasMinerals&&capacity<1);wreckOverlay.classList.add('open');wreckOverlay.setAttribute('aria-hidden','false')}
function drawWrecks(){for(const wreck of lootDrops){if(wreck.towing)continue;const point=project({x:wreck.x,y:0,z:wreck.z,r:30});if(!point||point.x<-30||point.x>W+30||point.y<-30||point.y>H+30)continue;const size=clamp(25000/point.z,5,17),jettison=wreck.dropType==='jettison';ctx.save();ctx.translate(point.x,point.y);ctx.rotate((performance.now()/1800+(Number(wreck.id)%10))*.3);ctx.shadowColor=jettison?'#66e4dd':'#ff9b5b';ctx.shadowBlur=14;ctx.strokeStyle=jettison?'#8dfff0':'#ffbd72';ctx.fillStyle=jettison?'rgba(21,104,105,.72)':'rgba(114,55,30,.6)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-size,-size*.25);ctx.lineTo(-size*.42,-size*.95);ctx.lineTo(size*.24,-size*.68);ctx.lineTo(size,.12*size);ctx.lineTo(size*.44,size*.84);ctx.lineTo(-size*.4,size*.66);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle=jettison?'#c8fff0':'#fff0b1';ctx.beginPath();ctx.arc(0,0,Math.max(1,size*.13),0,Math.PI*2);ctx.fill();ctx.restore();if(Math.hypot(player.x-wreck.x,player.z-wreck.z)<4000){ctx.save();ctx.textAlign='center';ctx.font='8px Space Mono';ctx.fillStyle=jettison?'#aaffee':'#ffe2b9';ctx.shadowColor=jettison?'#66e4dd':'#ff9b5b';ctx.shadowBlur=8;ctx.fillText(jettison?'CARGA SOLTA ? CLIQUE':'DESTROÃ‡OS ? CLIQUE',point.x,point.y+size+15);ctx.restore()}}}
async function attackRemoteShip(targetId){if(!multiplayerEnabled||!weaponSystem.installed||weaponSystem.ammo<1||shipHull<=0)return;try{const result=await socialRequest('ship-attack',{user_id:Number(targetId)});weaponSystem.ammo=Number(result.ammo);const target=remoteShips.find(ship=>Number(ship.id)===Number(targetId));const point=target?project({x:target.x,y:target.y||0,z:target.z}):null;weaponShots.push({x:W*.5,y:H-90,endX:point?.x??W*.5,endY:point?.y??H*.5,born:performance.now(),duration:230,targetId:null});combatMessage=result.destroyed?'NAVE DESTRUÃDA ? DESTROÃ‡OS DISPONÃVEIS':`IMPACTO ? ${result.damage} DANO ? CASCO INIMIGO ${result.hull}%`;if(result.destroyed){window.gameAudio?.play('explosion',{force:true});await pollCombatWorld()}else window.gameAudio?.play('shield');savePosition()}catch(error){combatMessage=error.message}}
async function pollCombatWorld(){if(!multiplayerEnabled||combatPollBusy)return;combatPollBusy=true;try{const response=await fetch(multiplayerApi+'?action=combat-world',{cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Falha no radar tÃ¡tico');const previousHull=shipHull;shipHull=Number(data.hull);lootDrops=Array.isArray(data.wrecks)?data.wrecks:[];if(previousHull<=0&&shipHull>0&&Number(data.stationId)>0){player.x=Number(data.x);player.z=Number(data.z);player.speed=0;await window.crewGame?.refreshShip?.()}if(shipHull<=0){destroyedOverlay.classList.add('open');destroyedOverlay.setAttribute('aria-hidden','false')}else{destroyedOverlay.classList.remove('open');destroyedOverlay.setAttribute('aria-hidden','true')}if(selectedWreck){const refreshed=lootDrops.find(item=>Number(item.id)===Number(selectedWreck.id));if(refreshed)openWreck(refreshed);else closeWreck()}}catch(error){}finally{combatPollBusy=false}}
document.querySelector('#wreckClose').addEventListener('click',closeWreck);wreckOverlay.addEventListener('click',event=>{if(event.target===wreckOverlay)closeWreck()});document.querySelector('#wreckCollect').addEventListener('click',async()=>{if(!selectedWreck)return;const button=document.querySelector('#wreckCollect');button.disabled=true;try{const result=await socialRequest('loot-claim',{wreck_id:Number(selectedWreck.id)});for(const [mineral,amount] of Object.entries(result.cargo||{})){miningState.oreCounts[mineral]=(Number(miningState.oreCounts[mineral])||0)+Number(amount)}miningState.ore=Object.values(miningState.oreCounts).reduce((sum,value)=>sum+value,0);energyUnits+=Number(result.energy)||0;document.querySelector('#wreckMessage').textContent='Carga coletada'+(Number(result.energy)>0?' ? energia +'+Number(result.energy)+' UE':' ? minerais adicionados ao compartimento');savePosition();await pollCombatWorld();closeWreck()}catch(error){document.querySelector('#wreckMessage').textContent=error.message;button.disabled=false}});
document.querySelector('#respawnButton').addEventListener('click',async()=>{const button=document.querySelector('#respawnButton');button.disabled=true;try{const result=await socialRequest('ship-respawn',{});player.x=Number(result.x);player.y=0;player.z=Number(result.z);player.yaw=0;player.speed=0;shipHull=Number(result.hull);fuelUnits=fuelCapacityUnits;destroyedOverlay.classList.remove('open');destroyedOverlay.setAttribute('aria-hidden','true');combatMessage='Nave reconstru?da perto de '+String(result.station?.name||'uma esta??o espacial');savePosition()}catch(error){document.querySelector('#respawnMessage').textContent=error.message}finally{button.disabled=false}});
function remoteShipRenderInfo(ship){const dx=ship.x-player.x,dz=ship.z-player.z,distance=Math.hypot(dx,Number(ship.y||0)-player.y,dz);if(distance>multiplayerShipVisibilityRange)return null;const point=project({x:ship.x,y:ship.y||0,z:ship.z});if(point&&point.x>72&&point.x<W-72&&point.y>72&&point.y<H-72)return{mode:'ship',point,distance};const angle=Math.atan2(dx,-dz)-player.yaw,ux=Math.sin(angle),uy=-Math.cos(angle),halfW=Math.max(20,W/2-45),halfH=Math.max(20,H/2-55),scale=Math.min(halfW/Math.max(Math.abs(ux),.0001),halfH/Math.max(Math.abs(uy),.0001));return{mode:'indicator',x:W/2+ux*scale,y:H/2+uy*scale,angle,distance}}
