      ctx.beginPath();ctx.moveTo(0,-size*1.8);ctx.lineTo(size*.48,-size*.9);ctx.lineTo(size*.42,size*1.2);ctx.lineTo(0,size*1.55);ctx.lineTo(-size*.42,size*1.2);ctx.lineTo(-size*.48,-size*.9);ctx.closePath();ctx.fill();ctx.stroke();
      ctx.shadowBlur=0;for(const side of [-1,1]){ctx.fillStyle='#8a9a88';ctx.strokeStyle='#d4cfa8';ctx.beginPath();ctx.roundRect(side*size*.52-size*.33,-size*.52,size*.66,size*.9,3);ctx.fill();ctx.stroke();ctx.beginPath();ctx.roundRect(side*size*.52-size*.33,size*.48,size*.66,size*.72,3);ctx.fill();ctx.stroke();ctx.fillStyle='rgba(103,190,211,.55)';ctx.fillRect(side*size*.52-size*.22,-size*.39,size*.44,.7);ctx.fillRect(side*size*.52-size*.22,size*.61,size*.44,.7)}
      ctx.fillStyle='#bdf7ef';ctx.beginPath();ctx.ellipse(0,-size*.88,size*.22,size*.35,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8bfff0';for(const ex of [-size*.3,size*.3]){ctx.beginPath();ctx.arc(ex,size*1.38,size*.12,0,Math.PI*2);ctx.fill()}ctx.restore();
