    ctx.beginPath();ctx.moveTo(0,-size*2.08);ctx.lineTo(size*.38,-size*1.2);ctx.lineTo(size*.52,-size*.55);ctx.lineTo(size*1.88,-size*.04);ctx.lineTo(size*2.28,size*.68);ctx.lineTo(size*.9,size*.44);ctx.lineTo(size*.72,size*1.12);ctx.lineTo(size*.4,size*.86);ctx.lineTo(size*.31,size*1.42);ctx.lineTo(0,size*1.18);ctx.lineTo(-size*.31,size*1.42);ctx.lineTo(-size*.4,size*.86);ctx.lineTo(-size*.72,size*1.12);ctx.lineTo(-size*.9,size*.44);ctx.lineTo(-size*2.28,size*.68);ctx.lineTo(-size*1.88,-size*.04);ctx.lineTo(-size*.52,-size*.55);ctx.lineTo(-size*.38,-size*1.2);ctx.closePath();ctx.fill();ctx.stroke();
    // Pain?is de armadura, trilhos e dois canhÃµes de ponta de asa.
