let rareAsteroidPollBusy=false;async function pollRareAsteroids(){if(!multiplayerEnabled||rareAsteroidPollBusy)return;rareAsteroidPollBusy=true;try{const response=await fetch(multiplayerApi+'?action=rare-asteroids',{cache:'no-store'}),data=await response.json();if(!response.ok)return;const visible=new Set();for(const item of data.asteroids||[]){visible.add(item.id);const existing=bodies.find(body=>body.rare&&body.id===item.id);if(existing)Object.assign(existing,item);else bodies.push(item)}for(let i=bodies.length-1;i>=0;i--){const body=bodies[i];if(body.rare&&!visible.has(body.id)){if(selected.id===body.id){selected=bodies.find(item=>item.id==='aurora')||bodies[0];miningState.active=false;miningState.status='Sinal do asteroide raro perdido'}bodies.splice(i,1)}}}catch(error){}finally{rareAsteroidPollBusy=false}}let iceAsteroidPollBusy=false;async function pollIceAsteroids(){if(!multiplayerEnabled||iceAsteroidPollBusy)return;iceAsteroidPollBusy=true;try{const response=await fetch(multiplayerApi+'?action=ice-asteroids',{cache:'no-store'}),data=await response.json();if(!response.ok)return;const visible=new Set();for(const item of data.asteroids||[]){visible.add(item.id);const existing=bodies.find(body=>body.ice&&body.id===item.id);if(existing)Object.assign(existing,item);else bodies.push(item)}for(let i=bodies.length-1;i>=0;i--){const body=bodies[i];if(body.ice&&!visible.has(body.id)){if(selected.id===body.id){selected=bodies.find(item=>item.id==='aurora')||bodies[0];miningState.active=false;miningState.status='Sinal do asteroide de gelo perdido'}bodies.splice(i,1)}}}catch(error){}finally{iceAsteroidPollBusy=false}}let multiplayerPollBusy=false;async function pollMultiplayer(){if(!multiplayerEnabled||multiplayerPollBusy)return;multiplayerPollBusy=true;try{const response=await fetch(multiplayerApi+'?action=players',{cache:'no-store'});if(!response.ok)throw new Error('SessÃ£o multiplayer indispon?vel');const data=await response.json();remoteShips=Array.isArray(data.players)?data.players:[];const status=document.querySelector('#multiplayerStatus');if(status){let dot=status.querySelector('i');if(!dot)dot=document.createElement('i');status.replaceChildren(dot,document.createTextNode('PILOTOS ONLINE Â· '+(remoteShips.length+1)))}}catch(error){const status=document.querySelector('#multiplayerStatus');if(status){let dot=status.querySelector('i');if(!dot)dot=document.createElement('i');status.replaceChildren(dot,document.createTextNode('MULTIPLAYER SEM CONEXÃƒO'))}}finally{multiplayerPollBusy=false}}
if(multiplayerEnabled){setInterval(()=>{if(positionReady)savePosition()},1000);setInterval(pollMultiplayer,1100);pollMultiplayer();setInterval(pollCombatWorld,1200);pollCombatWorld();setInterval(pollRareAsteroids,3000);pollRareAsteroids();setInterval(pollIceAsteroids,3000);pollIceAsteroids()}
